const L: string[] = [];
L.push("$ErrorActionPreference = 'Continue'");
L.push("$ua = 'Mozilla/5.0 (iPhone; CPU iPhone OS 17_0 like Mac OS X) AppleWebKit/605.1.15 Chrome/131 Mobile'");
L.push("$urls = @(");
L.push(" 'http://news.cnr.cn/native/gd/20260727/t20260727_527731759.shtml',");
L.push(" 'https://www.cssn.cn/skgz/bwyc/202604/t20260420_5980978.shtml',");
L.push(" 'https://legal.gmw.cn/2025-03/27/content_37930371.htm',");
L.push(" 'https://www.gov.cn/zhengce/2012-11/13/content_5713384.htm'");
L.push(")");
L.push("foreach ($u in $urls) {");
L.push(" try {");
L.push(" $r = Invoke-WebRequest -Uri $u -Proxy 'http://127.0.0.1:7897' -UserAgent $ua -TimeoutSec 45 -ErrorAction Stop");
L.push(" $bytes = $r.Content");
L.push(" $enc = [System.Text.Encoding]::GetEncoding('GB18030')");
L.push(" $html = $enc.GetString($bytes)");
L.push(" if ($html -notmatch '<meta') { $html = [System.Text.Encoding]::UTF8.GetString($bytes) }");
L.push(" $t = $html -replace '<script[\\s\\S]*?</script>',' ' -replace '<style[\\s\\S]*?</style>',' ' -replace '<[^>]+>',' '");
L.push(" $t = $t -replace '&nbsp;',' ' -replace '&amp;','&' -replace '&#39;',[char]39 -replace '&quot;',[char]34");
L.push(" $t = $t -replace '\\s+',' '");
L.push(" Write-Output ('===== ' + $u + ' OK ' + $r.StatusCode + ' len=' + $t.Length)");
L.push(" Write-Output $t.Substring(0, [Math]::Min(3800, $t.Length))");
L.push(" } catch { Write-Output ('===== ' + $u + ' FAIL ' + $_.Exception.Message.Split([Environment]::NewLine)[0]) }");
L.push("}");
await tools.write({ file_path: "C:\\Users\\jjq21\\AppData\\Local\\Temp\\ofm-st2.ps1", content: L.join("\n") });
const r = await tools.pwsh({ command: `& 'C:\\Users\\jjq21\\AppData\\Local\\Temp\\ofm-st2.ps1'`, description: "Fetch GBK articles via PowerShell", timeoutMs: 260000 });
const t = (x: any) => x.kind === "foreground" ? (x.stdout.text + (x.stderr.text || "") : JSON.stringify(x);
console.log(t(r).slice(0, 14000));
